#include <map>

using namespace std;

class MyCalendarThree {
    map<int, int> timeline;

public:
    MyCalendarThree() {}

    int book(int start, int end) {
        timeline[start]++;
        timeline[end]--;
        int ongoing = 0, res = 0;
        for (auto& [time, delta] : timeline) {
            ongoing += delta;
            res = max(res, ongoing);
        }
        return res;
    }
};
